-- =============================================================================
-- Migration 0041: K.3 Theorie B — De arctangensfunctie en primitiveren
-- =============================================================================
-- Gegenereerd door scripts/k3b-content.ts — niet met de hand bewerken.
--
-- In Theorie A stond de standaardvorm altijd al klaar. Hier moet je hem zelf
-- tevoorschijn halen, op twee manieren:
--
--     a/(px² + q)      → teller en noemer delen door q: (a/q)/((bx)² + 1)
--     a/(x² + bx + c)  → eerst kwadraatafsplitsen: a/((x - p)² + q)
--
-- Vier clusters: herschrijven naar a/((bx)² + 1), kwadraatafsplitsen in de
-- noemer, bepaalde integralen, en vlakdelen met de waarde van p.
--
-- Eigen topics en eigen clusters, zodat de controles aan het eind van de eerdere
-- K-migraties blijven kloppen en die migraties herhaalbaar blijven.
--
-- Eigen oefenvragen, geen boekopgaven. De 23 vragen met een integraal worden
-- nagerekend door src/content/primitieven.test.ts (content/hoofdstuk-k/k3b.json);
-- de ene vraag over het maximum van een breuk heeft geen integraal en staat daar
-- niet in.
--
-- Alleen toevoegen: geen DELETE, DROP, ALTER of UPDATE. Twee keer draaien
-- voegt niets dubbel toe.
--
--   • 1 hoofdstuk, 3 topics, 4 clusters
--   • 24 vragen met elk 4 stappen (96 stappen)
-- =============================================================================

BEGIN;

-- 1. Hoofdstuk
INSERT INTO public.chapters (slug, title, book_part, order_index, site)
VALUES ('k', $ksql$K — Voortgezette integraalrekening$ksql$, 4, 12, 'integralen')
ON CONFLICT (slug) DO NOTHING;

-- 2. Topics
INSERT INTO public.topics_new (slug, title, chapter_id, order_index, is_unlocked_by_default, site, category)
SELECT v.slug, v.title, (SELECT id FROM public.chapters WHERE slug = 'k' AND site = 'integralen'), v.order_index, true, 'integralen', v.category
FROM (VALUES
  ('k3b_primitiveren', $ksql$Primitiveren naar arctan: de vorm zoeken$ksql$, 20, 'primitiveren'),
  ('k3b_bepaald', $ksql$Bepaalde integralen naar arctan$ksql$, 21, 'integralen'),
  ('k3b_toepassing', $ksql$Vlakdelen met arctan$ksql$, 22, 'toepassingen')
) AS v(slug, title, order_index, category)
ON CONFLICT (slug) DO NOTHING;

-- 3. Clusters
INSERT INTO public.topic_clusters_new (topic_id, slug, title, order_index, site)
SELECT t.id, v.slug, v.title, v.order_index, 'integralen'
FROM (VALUES
  ('k3b_primitiveren', 'k3b_herschrijven', $ksql$Naar de vorm a/((bx)² + 1)$ksql$, 1),
  ('k3b_primitiveren', 'k3b_kwadraat', $ksql$Kwadraatafsplitsen in de noemer$ksql$, 2),
  ('k3b_bepaald', 'k3b_bepaald_exact', $ksql$Bepaalde integralen met arctan$ksql$, 1),
  ('k3b_toepassing', 'k3b_oppervlakte', $ksql$Oppervlakte en de waarde van p$ksql$, 1)
) AS v(topic_slug, slug, title, order_index)
JOIN public.topics_new t ON t.slug = v.topic_slug AND t.site = 'integralen'
ON CONFLICT (topic_id, slug) DO NOTHING;

-- 4. Vragen
INSERT INTO public.questions_new
