SELECT 'integralen', t.id, cl.id, v.latex_body, v.answer, v.latex_answer, v.difficulty, v.order_index, false, v.alternatives
FROM (VALUES
  ('k3b_primitiveren', 'k3b_herschrijven', $ksql$Primitiveer: $f(x) = \dfrac{6}{x^{2} + 9}$$ksql$, $ksql$2arctan(1/3 x) + c$ksql$, $ksql$F(x) = 2\arctan\left(\tfrac{1}{3}x\right) + c$ksql$, 1, 1, ARRAY[$ksql$2 arctan(x/3) + c$ksql$, $ksql$2arctan(x/3) + c$ksql$, $ksql$2atan(x/3) + c$ksql$, $ksql$2 atan(x/3) + c$ksql$]::text[]),
  ('k3b_primitiveren', 'k3b_herschrijven', $ksql$Primitiveer: $f(x) = \dfrac{1}{x^{2} + 25}$$ksql$, $ksql$1/5 arctan(1/5 x) + c$ksql$, $ksql$F(x) = \tfrac{1}{5}\arctan\left(\tfrac{1}{5}x\right) + c$ksql$, 1, 2, ARRAY[$ksql$1/5 arctan(x/5) + c$ksql$, $ksql$arctan(x/5)/5 + c$ksql$, $ksql$1/5 atan(x/5) + c$ksql$, $ksql$(1/5)arctan(x/5) + c$ksql$]::text[]),
